 {showScanner&&<Modal title="Barcode scanner" subtitle="Enter a barcode manually or use a connected scanner." onClose={()=>setShowScanner(false)}><div className="scanner-box"><ScanBarcode size={48}/><b>Ready to scan</b><p>Most USB/Bluetooth scanners work as keyboard input. Camera-based scanning requires a browser camera permission and scanner integration.</p><input className="field" autoFocus placeholder="Click here, then scan barcode" onKeyDown={e=>{if(e.key==='Enter'){const p=products.find(p=>p.barcode===e.currentTarget.value||p.sku===e.currentTarget.value);if(p){addToCart(p);setNotice(`${p.name} added to current cart.`);setShowScanner(false)}else setNotice('No product matches that barcode.')}}}/></div><div className="modal-actions"><button className="btn secondary" onClick={()=>setShowScanner(false)}>Close</button></div></Modal>}
