function Stat({title,value,change,positive,sub,icon:Icon}:any){return <div className="stat-card"><div className="stat-top"><span>{title}</span><div className="stat-icon"><Icon size={18}/></div></div><strong className="stat-value">{value}</strong><div className="stat-bottom"><span className={positive?'positive':'neutral'}>{positive&&'↗ '}{change}</span><span>{sub}</span></div></div>}
function Quick({icon:Icon,label,onClick}:any){return <button className="quick-action" onClick={onClick}><div><Icon size={20}/></div><span>{label}</span></button>}
function Transaction({initials,name,detail,amount,status}:any){return <div className="transaction-row"><div className="avatar customer-avatar">{initials}</div><div className="transaction-meta"><b>{name}</b><small>{detail}</small></div><div className="transaction-amount"><b>{amount}</b><small className={status==='Completed'?'positive':'pending'}>{status}</small></div></div>}
function Modal({title,subtitle,onClose,children,wide}:any){return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className={`modal ${wide?'modal-wide':''}`} role="dialog" aria-modal="true" aria-label={title}><div className="modal-header"><div><h2>{title}</h2><p>{subtitle}</p></div><button className="icon-btn" onClick={onClose}><X size={19}/></button></div>{children}</div></div>}
function Invoice({cart,total,customer}:any){return <div className="invoice-preview" id="invoice-print"><div className="invoice-brand"><div className="brand-mark"><ShoppingCart size={20}/></div><div><b>Dream POS</b><small>RETAIL STORE</small></div><span className="invoice-label">TAX INVOICE</span></div><div className="invoice-info"><div><small>INVOICE TO</small><b>{customer?.name||'Walk-in customer'}</b><span>{customer?.phone||customer?.email||'No customer contact selected'}</span></div><div><small>INVOICE NUMBER</small><b>INV-DRAFT-001</b><span>{new Date().toLocaleDateString('en-IN')}</span></div></div><table className="invoice-table"><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody>{cart.map((x:any)=><tr key={x.product.id}><td>{x.product.name}<small>{x.product.sku}</small></td><td>{x.qty}</td><td>{formatINR(x.product.price)}</td><td>{formatINR(x.product.price*x.qty)}</td></tr>)}</tbody></table><div className="invoice-total"><span>Subtotal</span><b>{formatINR(total)}</b><span>Tax</span><b>{formatINR(0)}</b><span className="invoice-grand">Total due</span><b className="invoice-grand">{formatINR(total)}</b></div><p className="invoice-thanks">Thank you for shopping with us!</p></div>}

