 const [rows,setRows]=useState<any[]>([]); const [plans,setPlans]=useState<any[]>([]); const [refs,setRefs]=useState<{products:any[];customers:any[];suppliers:any[];warehouses:any[];employees:any[];sales:any[];users:any[];stores:any[]}>({products:[],customers:[],suppliers:[],warehouses:[],employees:[],sales:[],users:[],stores:[]}); const [payrollAdjustments,setPayrollAdjustments]=useState<Record<string,{allowances:string;deductions:string}>>({}); const [loading,setLoading]=useState(true); const [busy,setBusy]=useState(false); const [q,setQ]=useState(''); const emptyForm={name:'',phone:'',email:'',address:'',category:'Utilities',description:'',amount:'',expenseDate:new Date().toISOString().slice(0,10),paymentMethod:'cash',supplierId:'',purchaseStatus:'received',productId:'',quantity:'1',unitCost:'0',code:'',fromWarehouseId:'',toWarehouseId:'',employeeId:'',date:new Date().toISOString().slice(0,10),status:'present',attendanceAction:role==='Employee'?'clock_in':'mark',leaveType:'Annual',startDate:'',endDate:'',reason:'',periodStart:'',periodEnd:'',entryDate:new Date().toISOString().slice(0,10),accountCode:'1000',accountName:'Cash',creditAccountCode:'4000',creditAccountName:'Sales Revenue',userRole:'cashier',password:'',storeId:'',deductions:'0',allowances:'0',stockMode:'set',taxNumber:'',delta:'1',stockReason:'',saleId:'',returnReason:'',quoteItemName:'',quoteCustomerId:'',quoteUnitPrice:'0',deliveryAddress:'',deliveryPhone:'',saasType:'tenant',tenantSlug:'',ownerEmail:'',planId:'',billingInterval:'monthly',maxStores:'1',maxUsers:'5',maxProducts:'1000',features:'POS,Inventory,Reports',salary:'0',department:'',jobTitle:'',taskTitle:'',taskDescription:'',taskStatus:'todo',priority:'medium',assignedTo:'',dueDate:''}; const [form,setForm]=useState(emptyForm);
