 const cfg=config[active];
 useEffect(()=>{let cancelled=false;const endpoints:[keyof typeof refs,string,string][]=[['products','/api/products','products'],['customers','/api/customers','customers'],['suppliers','/api/suppliers','suppliers'],['warehouses','/api/warehouses','warehouses'],['employees','/api/employees','employees'],['sales','/api/sales','sales'],['stores','/api/stores','stores']];const userEndpoints:(readonly [keyof typeof refs,string,string])[]=role==='Admin'||role==='Super Admin'?[['users','/api/users','users']]:role==='Manager'||role==='Supervisor'||role==='HR Manager'?[['users','/api/users?purpose=assignees','users']]:role==='Cashier'||role==='Salesman'?[['users','/api/users?purpose=delivery','users']]:[];Promise.all([...endpoints,...userEndpoints].map(async([key,url,field])=>{try{const response=await fetch(url,{cache:'no-store'});if(!response.ok)return [key,[]] as const;const data=await response.json();return [key,Array.isArray(data[field])?data[field]:[]] as const;}catch{return [key,[]] as const;}})).then(results=>{if(cancelled)return;setRefs(old=>{const next={...old};for(const [key,value] of results)(next as any)[key]=value;return next;});});return()=>{cancelled=true;};},[role]);
