 {active==='Expenses & Finance'&&<><label>Category *<select className="field" value={form.category} onChange={e=>setForm({...form,category:e.target.value})}><option>Utilities</option><option>Rent</option><option>Travel</option><option>Supplies</option><option>Payroll</option><option>Maintenance</option><option>Other</option></select></label><label>Description *<input className="field" required value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><label>Amount (₹) *<input className="field" required type="number" min="0.01" step="0.01" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></label><label>Expense date *<input className="field" required type="date" value={form.expenseDate} onChange={e=>setForm({...form,expenseDate:e.target.value})}/></label><label>Payment method<select className="field" value={form.paymentMethod} onChange={e=>setForm({...form,paymentMethod:e.target.value})}><option value="cash">Cash</option><option value="card">Card</option><option value="upi">UPI</option><option value="bank">Bank transfer</option><option value="other">Other</option></select></label></>}
 {active==='Purchases'&&<><label>Product *<select className="field" required value={form.productId} onChange={e=>{const selected=refs.products.find((p:any)=>String(p.id)===e.target.value);setForm({...form,productId:e.target.value,unitCost:selected?String(selected.cost_price??selected.price??form.unitCost):form.unitCost})}}><option value="">Select product…</option>{cfgOptions('products','id',(p:any)=>`${p.name} · ${p.sku} · stock ${p.stock??p.stock_qty??'—'}`).map(o=><option key={o.id} value={o.id}>{o.label}</option>)}</select></label><label>Supplier<select className="field" value={form.supplierId} onChange={e=>setForm({...form,supplierId:e.target.value})}><option value="">No supplier selected</option>{cfgOptions('suppliers','id',(x:any)=>`${x.name}${x.phone?' · '+x.phone:''}`).map(o=><option key={o.id} value={o.id}>{o.label}</option>)}</select></label><label>Quantity *<input className="field" required type="number" min="0.001" step="0.001" value={form.quantity} onChange={e=>setForm({...form,quantity:e.target.value})}/></label><label>Unit cost (₹) *<input className="field" required type="number" min="0" step="0.01" value={form.unitCost} onChange={e=>setForm({...form,unitCost:e.target.value})}/></label><label>Purchase status<select className="field" value={form.purchaseStatus} onChange={e=>setForm({...form,purchaseStatus:e.target.value})}><option value="ordered">Order stock (receive later)</option><option value="received">Received now</option></select></label></>}
