 {active==='Suppliers'&&<><label>Supplier name *<input className="field" required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Phone<input className="field" value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></label><label>Email<input className="field" type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Tax number<input className="field" value={form.taxNumber} onChange={e=>setForm({...form,taxNumber:e.target.value})}/></label><label>Address<input className="field" value={form.address} onChange={e=>setForm({...form,address:e.target.value})}/></label></>}
