 {active==='Warehouse Transfers'&&<><label>Source warehouse *<select className="field" required value={form.fromWarehouseId} onChange={e=>setForm({...form,fromWarehouseId:e.target.value})}><option value="">Select source…</option>{cfgOptions('warehouses','id',(w:any)=>`${w.name} (${w.code})`).map(o=><option key={o.id} value={o.id}>{o.label}</option>)}</select></label><label>Destination warehouse *<select className="field" required value={form.toWarehouseId} onChange={e=>setForm({...form,toWarehouseId:e.target.value})}><option value="">Select destination…</option>{cfgOptions('warehouses','id',(w:any)=>`${w.name} (${w.code})`).filter(o=>o.id!==form.fromWarehouseId).map(o=><option key={o.id} value={o.id}>{o.label}</option>)}</select></label><label>Product ID *<input className="field" required type="number" min="1" value={form.productId} onChange={e=>setForm({...form,productId:e.target.value})}/></label><label>Quantity *<input className="field" required type="number" min="0.001" step="0.001" value={form.quantity} onChange={e=>setForm({...form,quantity:e.target.value})}/></label><label>Transfer notes<input className="field" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label></>}
